import React from 'react';

function CorporateService() {
  return (
    <div className="container py-4">
      <h2 className="text-center text-primary mb-4">Dịch vụ tổ chức sự kiện công ty</h2>
      <p>
        Tổ chức hội nghị, gala, team building, lễ tổng kết chuyên nghiệp và hiệu quả là thế mạnh của chúng tôi.
      </p>
      <ul>
        <li>Thiết kế sự kiện theo mục tiêu doanh nghiệp</li>
        <li>Âm thanh, ánh sáng, sân khấu, backdrop</li>
        <li>MC, ca sĩ, nhóm nhảy, trò chơi tập thể</li>
        <li>Gói báo giá linh hoạt theo ngân sách</li>
      </ul>
    </div>
  );
}

export default CorporateService;
